import{_ as n,o as t,c as e,a2 as s}from"./chunks/framework.DIgx86D7.js";const m=JSON.parse('{"title":"A Take-away Prompt","description":"","frontmatter":{},"headers":[],"relativePath":"en/prompts.md","filePath":"en/prompts.md"}'),i={name:"en/prompts.md"};function o(p,a,l,r,c,d){return t(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="a-take-away-prompt" tabindex="-1">A Take-away Prompt <a class="header-anchor" href="#a-take-away-prompt" aria-label="Permalink to &quot;A Take-away Prompt&quot;">​</a></h1><p>One slice of an AI-native workflow: not every capability needs to become a system. Some can be packaged as a <strong>copy-paste prompt</strong> — an editor pastes it into any chatbot (ChatGPT / Claude / Gemini) and it just works, zero install, zero backend.</p><blockquote><p>VitePress code blocks have a <strong>built-in copy button</strong> (top-right on hover).</p></blockquote><p>Note: only <strong>representative</strong> dimensions and tags are shown here; the team actually uses the full 14-dimension, 400-plus-tag version (internal, not public). The point is packaging judgment into a portable prompt, not publishing the taxonomy itself.</p><h2 id="film-auto-tagging-prompt" tabindex="-1">Film auto-tagging prompt <a class="header-anchor" href="#film-auto-tagging-prompt" aria-label="Permalink to &quot;Film auto-tagging prompt&quot;">​</a></h2><p>Hit copy top-right, paste into any chatbot, and replace the last two lines with your film&#39;s title and plot.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You are a film-tagging assistant. I&#39;ll give you a film&#39;s title and plot;</span></span>
<span class="line"><span>pick fitting tags from the dimensions below.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Rules]</span></span>
<span class="line"><span>1. A film can span multiple dimensions, with multiple tags per dimension.</span></span>
<span class="line"><span>2. Prefer tags from the list; if something obviously fits but isn&#39;t listed, add it and mark it &quot;(extended)&quot;.</span></span>
<span class="line"><span>3. Pay special attention to the &quot;Emotion&quot; dimension — always pick one if there&#39;s a mood signal.</span></span>
<span class="line"><span>4. Give a one-line overall read first, then one line per tag: &quot;Dimension · Tag — one-line reason&quot;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Dimensions and representative tags (examples, extend sensibly)]</span></span>
<span class="line"><span>- Genre: comedy, drama, action, romance, horror, sci-fi, crime, documentary…</span></span>
<span class="line"><span>- Emotion: healing, tear-jerker, mind-bending, stress-relief, heartwarming, dark, romantic, toxic-romance…</span></span>
<span class="line"><span>- Theme: revenge, coming-of-age, family bonds, workplace, survival, comeback…</span></span>
<span class="line"><span>- Setting: prison, courtroom, outer space, underwater, haunted house…</span></span>
<span class="line"><span>- Era: period, WWII, future, British period…</span></span>
<span class="line"><span>- Audience: family, teens, adults, seniors…</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Film to tag]</span></span>
<span class="line"><span>Title: (fill here)</span></span>
<span class="line"><span>Plot: (fill here)</span></span></code></pre></div><h2 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h2><ul><li>The plot can be a distributor blurb or any synopsis you find — the fuller it is, the better the tags.</li><li>Want only some dimensions (say emotion + theme)? Add &quot;only output dimensions X and Y&quot; to the rules.</li><li>Want it stricter? Change rule 2 to &quot;use only tags from the list, no inventing&quot;.</li></ul><h2 id="why-do-it-this-way" tabindex="-1">Why do it this way <a class="header-anchor" href="#why-do-it-this-way" aria-label="Permalink to &quot;Why do it this way&quot;">​</a></h2><p>The product itself has full backend auto-tagging (whitelist-validated against the complete taxonomy, written back to the library). But often an editor just wants to &quot;quickly try-tag one film&quot; without opening the backend. Packaging that need as a prompt pushes the AI capability <strong>down to the chatbot in everyone&#39;s hands</strong> — that&#39;s the spirit of an AI-native workflow: capability follows the person, instead of being locked inside one system.</p><p>Want the general principles for &quot;writing judgment into a good prompt&quot;? See <a href="/film-brain/vp-preview/en/collab">Working with AI</a>.</p>`,12)])])}const u=n(i,[["render",o]]);export{m as __pageData,u as default};
